package net.civeira.phylax.feature.observe.observedembed.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AllowedOriginsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property allowed origins of observed embed ")
  void test_allowed_origins_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> AllowedOriginsVO.tryFrom(null));
    Assertions.assertEquals("one", AllowedOriginsVO.from("one").getAllowedOrigins());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> AllowedOriginsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AllowedOriginsVO.from("one").toString());
  }
}
